def last_at_most(nums, target):
    """Last index i with nums[i] <= target (assumes nums[0] <= target)."""
    lo, hi = 0, len(nums) - 1
    steps = 0
    while lo < hi:
        steps += 1
        if steps > 10:
            return "stuck in a loop!"
        mid = lo + (hi - lo) // 2
        if nums[mid] <= target:
            lo = mid          # mid might be the answer: keep it
        else:
            hi = mid - 1
    return lo

