def first_true(lo, hi, feasible):
    """Smallest x in [lo, hi] with feasible(x) True; feasible must be monotonic."""
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if feasible(mid):
            hi = mid          # mid works: the answer is mid or smaller
        else:
            lo = mid + 1      # mid fails: the answer is larger
    return lo

def isqrt(n):
    """Largest r with r * r <= n: one less than the first r whose square is too big."""
    return first_true(0, n + 1, lambda r: r * r > n) - 1

def hours_needed(jobs, speed):
    return sum((p + speed - 1) // speed for p in jobs)   # integer ceiling

print(isqrt(17), isqrt(16), isqrt(0))        # 4 4 0
print(hours_needed([3, 6, 7, 11], 4))        # 8

function lowerBound(nums, target) {
  let lo = 0
  let hi = nums.length                      // half-open: the answer may be nums.length
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2)
    if (nums[mid] < target) lo = mid + 1
    else hi = mid
  }
  return lo
}

